(function () {
  var invCount = 0;
  for (var cat in window.QORA_INVESTIGATIONS) {
    invCount += window.QORA_INVESTIGATIONS[cat].length;
  }
  var txCount = 0;
  for (var cat in window.QORA_THERAPIES) {
    txCount += window.QORA_THERAPIES[cat].length;
  }
  window.QORA_CATALOG_STATS = { investigations: invCount, therapies: txCount };
  // eslint-disable-next-line no-console
  if (typeof console !== 'undefined') console.log('[qora-catalog] ' + invCount + ' investigations, ' + txCount + ' therapies loaded.');
})();

